
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const $ = (id) => document.getElementById(id);

let selectedCharacter = "witch";

let running = false;
let paused = false;
let gameOver = false;

let score = 0;
let coins = 0;
let totalCoins = 0;
let speedLevel = 1;
let upgradeCost = 10;

let worldSpeed = 4;
let frame = 0;
let dragonActive = false;
let dragonX = -180;

let obstacles = [];
let coinItems = [];
let particles = [];

let duckHeld = false;
let sprintHeld = false;

const groundY = 330;

const player = {
  x: 135,
    y: groundY - 70,
      w: 54,
        h: 70,
          vy: 0,
            onGround: true,
              duck: false
              };

              // Escolher personagem
              document.querySelectorAll(".character-card").forEach(card => {
                card.addEventListener("click", () => {
                    document.querySelectorAll(".character-card")
                          .forEach(c => c.classList.remove("selected"));

                              card.classList.add("selected");
                                  selectedCharacter = card.dataset.character;
                                    });
                                    });

                                    // Botões principais
                                    $("startBtn").addEventListener("click", startGame);
                                    $("restartBtn").addEventListener("click", startGame);

                                    $("pauseBtn").addEventListener("click", () => {
                                      if (!running || gameOver) return;

                                        paused = !paused;

                                          $("pauseBtn").textContent =
                                              paused ? "Continuar" : "Pausar";

                                                if (!paused) requestAnimationFrame(loop);
                                                });

                                                // Loja de velocidade
                                                $("upgradeBtn").addEventListener("click", () => {
                                                  if (totalCoins >= upgradeCost) {
                                                      totalCoins -= upgradeCost;

                                                          speedLevel++;

                                                              upgradeCost = Math.floor(upgradeCost * 1.65);

                                                                  worldSpeed += 0.55;

                                                                      updateHUD();
                                                                          beep(660, 0.08);
                                                                            }
                                                                            });

                                                                            // Controles do celular
                                                                            function bindHold(id, setter) {
                                                                              const el = $(id);

                                                                                el.addEventListener("pointerdown", e => {
                                                                                    e.preventDefault();
                                                                                        setter(true);
                                                                                            el.setPointerCapture(e.pointerId);
                                                                                              });

                                                                                                ["pointerup", "pointercancel", "lostpointercapture"]
                                                                                                    .forEach(ev => {
                                                                                                          el.addEventListener(ev, () => setter(false));
                                                                                                              });
                                                                                                              }

                                                                                                              bindHold("jumpBtn", v => {
                                                                                                                if (v) jump();
                                                                                                                });

                                                                                                                bindHold("duckBtn", v => duckHeld = v);
                                                                                                                bindHold("runBtn", v => sprintHeld = v);

                                                                                                                // Controles do computador
                                                                                                                window.addEventListener("keydown", e => {
                                                                                                                  if (["Space", "ArrowUp", "ArrowDown"].includes(e.code)) {
                                                                                                                      e.preventDefault();
                                                                                                                        }

                                                                                                                          if (e.code === "Space" || e.code === "ArrowUp") {
                                                                                                                              if (!e.repeat) jump();
                                                                                                                                }

                                                                                                                                  if (e.code === "KeyD" || e.code === "ArrowDown") {
                                                                                                                                      duckHeld = true;
                                                                                                                                        }

                                                                                                                                          if (
                                                                                                                                              e.code === "KeyS" ||
                                                                                                                                                  e.code === "ShiftLeft" ||
                                                                                                                                                      e.code === "ShiftRight"
                                                                                                                                                        ) {
                                                                                                                                                            sprintHeld = true;
                                                                                                                                                              }
                                                                                                                                                              });

                                                                                                                                                              window.addEventListener("keyup", e => {
                                                                                                                                                                if (e.code === "KeyD" || e.code === "ArrowDown") {
                                                                                                                                                                    duckHeld = false;
                                                                                                                                                                      }

                                                                                                                                                                        if (
                                                                                                                                                                            e.code === "KeyS" ||
                                                                                                                                                                                e.code === "ShiftLeft" ||
                                                                                                                                                                                    e.code === "ShiftRight"
                                                                                                                                                                                      ) {
                                                                                                                                                                                          sprintHeld = false;
                                                                                                                                                                                            }
                                                                                                                                                                                            });

                                                                                                                                                                                            // Pular
                                                                                                                                                                                            function jump() {
                                                                                                                                                                                              if (
                                                                                                                                                                                                  running &&
                                                                                                                                                                                                      !paused &&
                                                                                                                                                                                                          !gameOver &&
                                                                                                                                                                                                              player.onGround
                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                    player.vy = -13.5;
                                                                                                                                                                                                                        player.onGround = false;
                                                                                                                                                                                                                            beep(420, 0.05);
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                              }

                                                                                                                                                                                                                              // Começar ou reiniciar
                                                                                                                                                                                                                              function startGame() {
                                                                                                                                                                                                                                $("startScreen").classList.add("hidden");
                                                                                                                                                                                                                                  $("gameScreen").classList.remove("hidden");
                                                                                                                                                                                                                                    $("message").classList.add("hidden");

                                                                                                                                                                                                                                      score = 0;
                                                                                                                                                                                                                                        coins = 0;
                                                                                                                                                                                                                                          speedLevel = 1;
                                                                                                                                                                                                                                            upgradeCost = 10;
                                                                                                                                                                                                                                              worldSpeed = 4;
                                                                                                                                                                                                                                                frame = 0;

                                                                                                                                                                                                                                                  dragonActive = false;
                                                                                                                                                                                                                                                    dragonX = -180;

                                                                                                                                                                                                                                                      obstacles = [];
                                                                                                                                                                                                                                                        coinItems = [];
                                                                                                                                                                                                                                                          particles = [];

                                                                                                                                                                                                                                                            gameOver = false;
                                                                                                                                                                                                                                                              paused = false;
                                                                                                                                                                                                                                                                running = true;

                                                                                                                                                                                                                                                                  player.y = groundY - player.h;
                                                                                                                                                                                                                                                                    player.vy = 0;
                                                                                                                                                                                                                                                                      player.onGround = true;
                                                                                                                                                                                                                                                                        player.duck = false;

                                                                                                                                                                                                                                                                          $("pauseBtn").textContent = "Pausar";

                                                                                                                                                                                                                                                                            updateHUD();

                                                                                                                                                                                                                                                                              requestAnimationFrame(loop);
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                              // Atualizar informações da tela
                                                                                                                                                                                                                                                                              function updateHUD() {
                                                                                                                                                                                                                                                                                $("score").textContent = Math.floor(score);
                                                                                                                                                                                                                                                                                  $("runCoins").textContent = coins;
                                                                                                                                                                                                                                                                                    $("coinTotal").textContent = totalCoins;

                                                                                                                                                                                                                                                                                      $("upgradeCost").textContent = upgradeCost;
                                                                                                                                                                                                                                                                                        $("speedLevel").textContent = "Nível " + speedLevel;

                                                                                                                                                                                                                                                                                          $("upgradeBtn").disabled =
                                                                                                                                                                                                                                                                                              totalCoins < upgradeCost;

                                                                                                                                                                                                                                                                                                $("dragonStatus").textContent =
                                                                                                                                                                                                                                                                                                    dragonActive
                                                                                                                                                                                                                                                                                                          ? "🐉 O dragão está vindo!"
                                                                                                                                                                                                                                                                                                                : "🐉 O dragão ainda está dormindo…";
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                // Loop principal
                                                                                                                                                                                                                                                                                                                function loop() {
                                                                                                                                                                                                                                                                                                                  if (!running || paused || gameOver) return;

                                                                                                                                                                                                                                                                                                                    update();
                                                                                                                                                                                                                                                                                                                      draw();

                                                                                                                                                                                                                                                                                                                        requestAnimationFrame(loop);
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                        // Atualização do jogo
                                                                                                                                                                                                                                                                                                                        function update() {
                                                                                                                                                                                                                                                                                                                          frame++;

                                                                                                                                                                                                                                                                                                                            const sprint = sprintHeld ? 1.75 : 1;
                                                                                                                                                                                                                                                                                                                              const speed = worldSpeed * sprint;

                                                                                                                                                                                                                                                                                                                                score += 0.55 * sprint;

                                                                                                                                                                                                                                                                                                                                  // Dragão aparece com 1000 pontos
                                                                                                                                                                                                                                                                                                                                    if (score >= 1000 && !dragonActive) {
                                                                                                                                                                                                                                                                                                                                        dragonActive = true;
                                                                                                                                                                                                                                                                                                                                            dragonX = canvas.width + 50;

                                                                                                                                                                                                                                                                                                                                                showMessage("O DRAGÃO ACORDOU! 🐉", 900);
                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                    // Criar obstáculos
                                                                                                                                                                                                                                                                                                                                                      if (frame % 82 === 0) {
                                                                                                                                                                                                                                                                                                                                                          spawnObstacle();
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                              // Criar moedas
                                                                                                                                                                                                                                                                                                                                                                if (frame % 54 === 0) {
                                                                                                                                                                                                                                                                                                                                                                    spawnCoins();
                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                        // Abaixar
                                                                                                                                                                                                                                                                                                                                                                          player.duck = duckHeld && player.onGround;

                                                                                                                                                                                                                                                                                                                                                                            // Física do pulo
                                                                                                                                                                                                                                                                                                                                                                              if (!player.onGround) {
                                                                                                                                                                                                                                                                                                                                                                                  player.vy += 0.62;
                                                                                                                                                                                                                                                                                                                                                                                      player.y += player.vy;

                                                                                                                                                                                                                                                                                                                                                                                          if (player.y >= groundY - player.h) {
                                                                                                                                                                                                                                                                                                                                                                                                player.y = groundY - player.h;
                                                                                                                                                                                                                                                                                                                                                                                                      player.vy = 0;
                                                                                                                                                                                                                                                                                                                                                                                                            player.onGround = true;
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                    // Mover obstáculos
                                                                                                                                                                                                                                                                                                                                                                                                                      obstacles.forEach(o => o.x -= speed);

                                                                                                                                                                                                                                                                                                                                                                                                                        obstacles = obstacles.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                            o => o.x + o.w > -30
                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                // Mover moedas
                                                                                                                                                                                                                                                                                                                                                                                                                                  coinItems.forEach(c => {
                                                                                                                                                                                                                                                                                                                                                                                                                                      c.x -= speed;
                                                                                                                                                                                                                                                                                                                                                                                                                                          c.spin += 0.12;
                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                              coinItems = coinItems.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                  c => c.x > -30 && !c.taken
                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Dragão perseguindo
                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (dragonActive) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            dragonX -= Math.max(1.2, speed * 0.25);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (frame % 130 === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      particles.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              x: dragonX + 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      y: groundY - 75,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              life: 40
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (dragonX < player.x + 30) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  endGame("O dragão alcançou você! 🐉");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Fogo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            particles.forEach(p => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p.x -= speed + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p.life--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        particles = particles.filter(p => p.life > 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Colisão
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const ph = player.duck ? 38 : player.h;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const py = player.duck
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ? groundY - 38
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : player.y;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const hitbox = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            x: player.x + 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                y: py + 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    w: player.w - 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        h: ph - 12
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const o of obstacles) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const box = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      x: o.x + 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            y: o.y + 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  w: o.w - 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        h: o.h - 7
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (rect(hitbox, box)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      endGame("Ops! Você bateu em um obstáculo.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Pegar moedas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (const c of coinItems) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                !c.taken &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rect(hitbox, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              x: c.x - 13,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      y: c.y - 13,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              w: 26,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      h: 26
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      c.taken = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            coins++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  totalCoins++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        beep(820, 0.04);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (frame % 10 === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    updateHUD();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Criar obstáculos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function spawnObstacle() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const kinds = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "rock",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "river",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "hole",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "log"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const kind =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                kinds[Math.floor(Math.random() * kinds.length)];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const data = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rock: { w: 45, h: 37 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          river: { w: 92, h: 24 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              hole: { w: 76, h: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  log: { w: 86, h: 34 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const d = data[kind];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        obstacles.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            kind,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                x: canvas.width + 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    y: groundY - d.h,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        w: d.w,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            h: d.h
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Criar moedas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function spawnCoins() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const y = groundY - 85 - Math.random() * 85;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (let i = 0; i < 4; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      coinItems.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            x: canvas.width + 30 + i * 34,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  y: y - Math.sin(i / 3 * Math.PI) * 12,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        spin: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              taken: false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Verificar colisões
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function rect(a, b) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          a.x < b.x + b.w &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              a.x + a.w > b.x &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  a.y < b.y + b.h &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a.y + a.h > b.y
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Fim de jogo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function endGame(msg) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          gameOver = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            running = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $("message").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  msg +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "<br><small>Pontuação: " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Math.floor(score) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              " · Moedas nesta corrida: " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  coins +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "</small>" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "<br><small>Toque em Recomeçar para tentar novamente.</small>";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $("message").classList.remove("hidden");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              updateHUD();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Mensagem temporária
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function showMessage(text, ms) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const el = $("message");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  el.textContent = text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    el.classList.remove("hidden");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!gameOver) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                el.classList.add("hidden");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }, ms);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      